const { createHttpError } = require('./personnelValidation');

/**
 * A cleaning team is a reusable crew the administrator maintains once and
 * dispatches as a unit when a report needs more than one pair of hands.
 */
const TEAM_ID_PATTERN = /^TEAM-[0-9]{4}$/;

const MAX_TEAM_NAME_LENGTH = 80;
const MAX_TEAM_DESCRIPTION_LENGTH = 300;

/** The crew needs at least this many people to be worth dispatching. */
const MINIMUM_TEAM_MEMBERS = 2;

const CONTROL_CHARACTER_PATTERN = /[\u0000-\u001f\u007f]/;

/**
 * Normalises a team id.
 *
 * Team ids are generated by the database (TEAM-0001, TEAM-0002, ...) but they
 * still arrive from clients, so they are checked rather than trusted.
 */
const normalizeTeamId = (value, fieldName = 'teamId') => {
  if (value === undefined || value === null || value === '') {
    return null;
  }

  if (typeof value !== 'string') {
    throw createHttpError(400, `${fieldName} must be a string.`);
  }

  const normalized = value.trim().toUpperCase();

  if (!TEAM_ID_PATTERN.test(normalized)) {
    throw createHttpError(400, `${fieldName} must look like TEAM-0001.`);
  }

  return normalized;
};

const normalizeTeamName = (value) => {
  if (typeof value !== 'string') {
    throw createHttpError(400, 'Team name must be a string.');
  }

  const normalized = value.trim().replace(/\s+/g, ' ');

  if (!normalized) {
    throw createHttpError(400, 'Team name is required.');
  }

  if (normalized.length > MAX_TEAM_NAME_LENGTH) {
    throw createHttpError(
      400,
      `Team name must be at most ${MAX_TEAM_NAME_LENGTH} characters.`
    );
  }

  if (CONTROL_CHARACTER_PATTERN.test(normalized)) {
    throw createHttpError(400, 'Team name contains invalid characters.');
  }

  return normalized;
};

const normalizeTeamDescription = (value) => {
  if (value === undefined || value === null) {
    return null;
  }

  if (typeof value !== 'string') {
    throw createHttpError(400, 'Team description must be a string.');
  }

  const normalized = value.trim().replace(/\s+/g, ' ');

  if (!normalized) {
    return null;
  }

  if (normalized.length > MAX_TEAM_DESCRIPTION_LENGTH) {
    throw createHttpError(
      400,
      `Team description must be at most ${MAX_TEAM_DESCRIPTION_LENGTH} characters.`
    );
  }

  if (CONTROL_CHARACTER_PATTERN.test(normalized)) {
    throw createHttpError(400, 'Team description contains invalid characters.');
  }

  return normalized;
};

/**
 * Normalises a list of personnel ids into the membership of a team.
 *
 * The list is de-duplicated and upper-cased because the same person may be
 * picked twice in the admin UI, and because personnel ids are upper-case
 * everywhere else in the system.
 */
const normalizeTeamMemberIds = (value) => {
  if (!Array.isArray(value)) {
    throw createHttpError(400, 'Team members must be an array.');
  }

  if (value.length > 100) {
    throw createHttpError(400, 'A team cannot have more than 100 members.');
  }

  const ids = value.map((personnelId) => {
    if (typeof personnelId !== 'string') {
      throw createHttpError(400, 'Every team member ID must be a string.');
    }

    const trimmed = personnelId.trim().toUpperCase();

    if (!/^PERS-[0-9]{4}$/.test(trimmed)) {
      throw createHttpError(400, 'Team member IDs must use the PERS-XXXX format.');
    }

    return trimmed;
  });

  return [...new Set(ids)];
};

/**
 * Normalises the leader of a team.
 *
 * A team may exist without a leader (every team created before leaders were
 * editable), so null and the empty string both mean "no leader" rather than
 * being an error. When an id is present it is the same PERS-XXXX shape the
 * membership list uses, because the leader is a member of the crew.
 */
const normalizeTeamLeaderId = (value, fieldName = 'leaderId') => {
  if (value === undefined || value === null || value === '') {
    return null;
  }

  if (typeof value !== 'string') {
    throw createHttpError(400, `${fieldName} must be a string.`);
  }

  const normalized = value.trim().toUpperCase();

  if (!normalized) {
    return null;
  }

  if (!/^PERS-[0-9]{4}$/.test(normalized)) {
    throw createHttpError(400, `${fieldName} must use the PERS-XXXX format.`);
  }

  return normalized;
};

/**
 * The leader id in a payload, preferring the camelCase wire name.
 *
 * Returns undefined when the caller did not mention a leader at all, so an
 * update can tell "leave the leader alone" from "clear the leader".
 */
const readLeaderId = (body) => {
  const hasLeaderKey =
    body.leaderId !== undefined ||
    body.leader_id !== undefined ||
    body.leaderPersonnelId !== undefined ||
    body.leader_personnel_id !== undefined;

  if (!hasLeaderKey) return undefined;

  return normalizeTeamLeaderId(
    body.leaderId ?? body.leader_id ?? body.leaderPersonnelId ??
      body.leader_personnel_id
  );
};

/**
 * Validates the payload for creating a cleaning team.
 */
const validateCreateTeamPayload = (body = {}) => {
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    throw createHttpError(400, 'Request body must be a JSON object.');
  }

  const teamName = normalizeTeamName(body.teamName ?? body.team_name);
  const description = normalizeTeamDescription(
    body.description ?? body.team_description
  );
  const parentTeamId = normalizeTeamId(
    body.parentTeamId ?? body.parent_team_id,
    'parentTeamId'
  );

  const memberIds = body.memberIds ?? body.member_ids ?? body.personnelIds;
  const members = memberIds === undefined ? null : normalizeTeamMemberIds(memberIds);
  const leaderId = readLeaderId(body);

  return {
    teamName,
    description,
    parentTeamId,
    leaderId: leaderId === undefined ? null : leaderId,
    memberIds: members,
  };
};

/**
 * Validates a partial update to a cleaning team.
 *
 * Only the keys actually present come back, so the caller can tell "clear the
 * description" from "leave the description alone".
 */
const validateUpdateTeamPayload = (body = {}) => {
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    throw createHttpError(400, 'Request body must be a JSON object.');
  }

  const updates = {};

  if (body.teamName !== undefined || body.team_name !== undefined) {
    updates.teamName = normalizeTeamName(body.teamName ?? body.team_name);
  }

  if (body.description !== undefined || body.team_description !== undefined) {
    updates.description = normalizeTeamDescription(
      body.description ?? body.team_description
    );
  }

  if (body.parentTeamId !== undefined || body.parent_team_id !== undefined) {
    updates.parentTeamId = normalizeTeamId(
      body.parentTeamId ?? body.parent_team_id,
      'parentTeamId'
    );
  }

  if (body.memberIds !== undefined || body.member_ids !== undefined) {
    updates.memberIds = normalizeTeamMemberIds(body.memberIds ?? body.member_ids);
  }

  if (
    body.leaderId !== undefined ||
    body.leader_id !== undefined ||
    body.leaderPersonnelId !== undefined ||
    body.leader_personnel_id !== undefined
  ) {
    updates.leaderId = readLeaderId(body);
  }

  if (Object.keys(updates).length === 0) {
    throw createHttpError(400, 'Nothing to update.');
  }

  return updates;
};

module.exports = {
  TEAM_ID_PATTERN,
  MINIMUM_TEAM_MEMBERS,
  MAX_TEAM_NAME_LENGTH,
  MAX_TEAM_DESCRIPTION_LENGTH,
  normalizeTeamId,
  normalizeTeamName,
  normalizeTeamDescription,
  normalizeTeamMemberIds,
  normalizeTeamLeaderId,
  validateCreateTeamPayload,
  validateUpdateTeamPayload,
};
